  "recovered_c": "uint64_t fn_19(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (out_cap < len) {\n    return VERA_ERR;\n  }\n\n  if (len > 0) {\n    for (size_t i = 0; i < len; i++) {\n      uint8_t encoded_byte = (arg >> (i % 8 * 8)) & 0xFF;\n      if ((i * (i + 1) & 1) != 0 || 1) {\n        encoded_byte = (encoded_byte ^ (i << 7)) * 0x6B + 0x1000;\n      }\n      out[i] = (encoded_byte << (i % 8) | encoded_byte >> (8 - (i % 8))) ^ in[i] ^ (uint8_t)i;\n    }\n  }\n\n  return len;\n}"
